def round_robin(groups: list[list[int]]) -> list[int]:
    """Take one item from each nonempty group in group order each round.

    Continue until all groups are exhausted, preserving order within each
    group. Do not modify the groups, their values, or the outer collection.
    """
    result: list[int] = []
    for index in range(max((len(group) for group in groups), default=0)):
        for group in groups:
            if index < len(group):
                result.append(group[index])
    return result
import unittest

from solution import round_robin


class RoundRobinTests(unittest.TestCase):
    def test_equal_length_groups(self) -> None:
        self.assertEqual(round_robin([[1, 2], [3, 4], [5, 6]]),
                         [1, 3, 5, 2, 4, 6])

    def test_uneven_groups_and_empty_groups(self) -> None:
        self.assertEqual(round_robin([[], [1, 2, 3], [4], [], [5, 6], []]),
                         [1, 4, 5, 2, 6, 3])

    def test_empty_inputs(self) -> None:
        self.assertEqual(round_robin([]), [])
        self.assertEqual(round_robin([[], [], []]), [])

    def test_preserves_values_and_input_collections(self) -> None:
        groups = [[0, -2, 0], [7, 7], [], [-5]]
        original_groups = groups.copy()
        original_values = [group.copy() for group in groups]

        self.assertEqual(round_robin(groups), [0, 7, -5, -2, 7, 0])
        self.assertEqual(groups, original_values)
        for group, original in zip(groups, original_groups):
            self.assertIs(group, original)
        self.assertEqual(round_robin(groups), [0, 7, -5, -2, 7, 0])

    def test_shared_group_is_preserved(self) -> None:
        shared = [1, 2]
        self.assertEqual(round_robin([shared, shared]), [1, 1, 2, 2])
        self.assertEqual(shared, [1, 2])


if __name__ == "__main__":
    unittest.main()
